import { loadFont as loadAnton } from "@remotion/google-fonts/Anton";
import { loadFont as loadInter } from "@remotion/google-fonts/Inter";
import { loadFont as loadMono } from "@remotion/google-fonts/SpaceMono";
import React from "react";
import { AbsoluteFill, Audio, Easing, Img, interpolate, staticFile, useCurrentFrame } from "remotion";
import { PALAVRAS } from "./palavras";
import { VOZ_V3_FIM, toOld } from "./mapa-v4";

// FOURP (johny Fabrício) · v4 = v3 com a voz em 1,25x (mapa-v4.ts). v3 = a v2 com a voz nova (Roger, mais dinâmica, pausas de ~0,16 s). As cenas seguem escritas no
// tempo da voz antiga; o relógio do vídeo passa por toOld (mapa-v3.ts), palavra por palavra.
// v2: O o diretor pediu "mais próximo da referência, com animações mais parecidas e mais dinamismo".
// Da referência (src/video-1.mp4, Trafega Auto) vêm: título que se monta palavra por palavra no ritmo da fala (cada palavra
// entra cinza, desfocada, vindo da direita, e acende), etiqueta pequena em letra de máquina acima do título, ambientes em 3D
// com a câmera sempre andando (aqui a fachada de uma empresa no lugar da oficina), radar grande com raios, mapa e balões,
// trocas por clarão de luz e névoa, revelação da marca com raios de luz e a chamada com o ambiente apagado atrás.
// Cores e logo continuam os da Fourp (#0E0E0E, #E50914, #F8F8F8). Mesma voz da v1 (public/johny/voz-v1.wav, pausas curtas).
// Tempos = tempos da voz (t = 0 é o começo da voz; o vídeo tem LEAD de entrada).

const { fontFamily: A } = loadAnton("normal", { weights: ["400"], subsets: ["latin", "latin-ext"] });
const { fontFamily: I } = loadInter("normal", { weights: ["500", "600", "700", "800"], subsets: ["latin", "latin-ext"] });
const { fontFamily: M } = loadMono("normal", { weights: ["400", "700"], subsets: ["latin", "latin-ext"] });

export const FP4_FPS = 30;
const LEAD = 0.3;
export const FP4_FRAMES = Math.round((VOZ_V3_FIM + LEAD + 1.4) * FP4_FPS);

const BLACK = "#0E0E0E";
const RED = "#E50914";
const WHITE = "#F8F8F8";
const GREY = "#8B8B8B";
const glowRed = (s = 1) => `0 0 ${18 * s}px rgba(229,9,20,0.8), 0 0 ${48 * s}px rgba(229,9,20,0.35)`;

const cl = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;
const OUT = Easing.bezier(0.16, 1, 0.3, 1);
const BACK = Easing.out(Easing.back(1.7));
const INOUT = Easing.bezier(0.65, 0, 0.35, 1);
const k = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: OUT });
const pop = (t: number, a: number, d = 0.45) => interpolate(t, [a, a + d], [0, 1], { ...cl, easing: BACK });
const lin = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], cl);
const io = (t: number, a: number, b: number) => interpolate(t, [a, b], [0, 1], { ...cl, easing: INOUT });
const bump = (t: number, a: number, d = 0.35) => (t < a || t > a + d ? 0 : Math.sin(((t - a) / d) * Math.PI) * (1 - (t - a) / d));
const mix = (a: number, b: number, p: number) => a + (b - a) * p;

// trocas de cena (tempo da voz)
const T2 = 8.42, T3 = 13.62, T4 = 20.48, T5 = 30.86, T6 = 35.64, T7 = 39.34, T8 = 43.62;

// ───────── título palavra por palavra ─────────
type TW = [string, number, boolean?]; // palavra, tempo em que entra, vermelha
type TLine = { size: number; words: TW[] };
const Word: React.FC<{ t: number; w: TW; size: number }> = ({ t, w: [txt, at, red], size }) => {
  const e = k(t, at - 0.04, 0.32);
  const lit = lin(t, at + 0.06, at + 0.34);
  const col = red ? `rgb(${mix(110, 229, lit).toFixed(0)},${mix(110, 9, lit).toFixed(0)},${mix(110, 20, lit).toFixed(0)})` : `rgb(${mix(110, 248, lit).toFixed(0)},${mix(110, 248, lit).toFixed(0)},${mix(110, 248, lit).toFixed(0)})`;
  return (
    <span style={{ display: "inline-block", marginRight: size * 0.2, color: col, opacity: Math.min(1, e * 1.8), filter: `blur(${((1 - e) * 10).toFixed(1)}px)`, transform: `translateX(${((1 - e) * size * 0.55).toFixed(1)}px)`, textShadow: red && lit > 0.5 ? glowRed(0.7 * lit) : "none" }}>
      {txt}
    </span>
  );
};
const Title: React.FC<{ t: number; lines: TLine[]; top?: number; out?: number; tag?: [string, number] }> = ({ t, lines, top = 190, out, tag }) => {
  const o = out === undefined ? 0 : lin(t, out, out + 0.18);
  return (
    <div style={{ position: "absolute", left: 100, right: 100, top, display: "flex", flexDirection: "column", alignItems: "center", opacity: 1 - o, filter: o > 0 ? `blur(${(o * 10).toFixed(1)}px)` : undefined }}>
      {tag ? (
        <div style={{ fontFamily: M, fontWeight: 700, fontSize: 22, letterSpacing: "0.32em", color: RED, border: `2px solid rgba(229,9,20,0.6)`, padding: "6px 18px", marginBottom: 16, opacity: k(t, tag[1], 0.4), textShadow: "0 0 10px rgba(229,9,20,0.6)" }}>{tag[0]}</div>
      ) : null}
      {lines.map((l, i) => (
        <div key={i} style={{ fontFamily: A, fontSize: l.size, lineHeight: 1.1, whiteSpace: "nowrap", textAlign: "center", textTransform: "uppercase", marginRight: -l.size * 0.2 }}>
          {l.words.map((w, j) => <Word key={j} t={t} w={w} size={l.size} />)}
        </div>
      ))}
    </div>
  );
};

// ───────── mundo 3D (CSS): câmera em x, y (altura), z, olhando para −z ─────────
type Cam = { x: number; y: number; z: number; pitch: number; yaw: number; roll?: number };
const F = 1100;
// câmera em (x, y, z) mirando o ponto (tx, ty, tz)
const look = (x: number, y: number, z: number, tx: number, ty: number, tz: number, roll = 0): Cam => {
  const h = Math.hypot(tx - x, z - tz);
  return { x, y, z, yaw: (Math.atan2(tx - x, z - tz) * 180) / Math.PI, pitch: (-Math.atan2(y - ty, h) * 180) / Math.PI, roll };
};
const World: React.FC<{ cam: Cam; children: React.ReactNode; style?: React.CSSProperties }> = ({ cam, children, style }) => (
  <AbsoluteFill style={{ perspective: F, perspectiveOrigin: "50% 50%", overflow: "hidden", ...style }}>
    <div style={{ position: "absolute", left: 540, top: 960, width: 0, height: 0, transformStyle: "preserve-3d", transform: `translateZ(${F}px) rotateZ(${cam.roll ?? 0}deg) rotateX(${cam.pitch}deg) rotateY(${cam.yaw}deg) translate3d(${-cam.x}px, ${cam.y}px, ${-cam.z}px)` }}>
      {children}
    </div>
  </AbsoluteFill>
);
// plano no mundo: centro em (x, y, z), y para cima
const P3: React.FC<{ x?: number; y?: number; z?: number; rx?: number; ry?: number; rz?: number; w: number; h: number; style?: React.CSSProperties; children?: React.ReactNode }> = ({ x = 0, y = 0, z = 0, rx = 0, ry = 0, rz = 0, w, h, style, children }) => (
  <div style={{ position: "absolute", left: -w / 2, top: -h / 2, width: w, height: h, transform: `translate3d(${x}px, ${-y}px, ${z}px) rotateY(${ry}deg) rotateX(${rx}deg) rotateZ(${rz}deg)`, transformStyle: "preserve-3d", ...style }}>
    {children}
  </div>
);
// caixa: base em y, centro em x/z
const Box: React.FC<{ x: number; y?: number; z: number; w: number; h: number; d: number; front: React.CSSProperties; side?: React.CSSProperties; top?: React.CSSProperties; children?: React.ReactNode }> = ({ x, y = 0, z, w, h, d, front, side = { background: "#121212" }, top = { background: "#1c1c1c" }, children }) => {
  const cy = y + h / 2;
  return (
    <>
      <P3 x={x} y={cy} z={z + d / 2} w={w} h={h} style={front}>{children}</P3>
      <P3 x={x - w / 2} y={cy} z={z} ry={-90} w={d} h={h} style={side} />
      <P3 x={x + w / 2} y={cy} z={z} ry={90} w={d} h={h} style={side} />
      <P3 x={x} y={y + h} z={z} rx={90} w={w} h={d} style={top} />
    </>
  );
};
const Floor: React.FC<{ glow?: number; z?: number }> = ({ glow = 0.4, z = -900 }) => (
  <>
    <P3 x={0} y={0} z={z} rx={90} w={4400} h={3600} style={{ background: `radial-gradient(ellipse at 50% 40%, rgba(229,9,20,${(0.1 * glow).toFixed(3)}) 0%, rgba(14,14,14,0) 55%), repeating-linear-gradient(0deg, rgba(255,255,255,0.05) 0 2px, transparent 2px 160px), repeating-linear-gradient(90deg, rgba(255,255,255,0.05) 0 2px, transparent 2px 160px), #0c0c0c` }} />
    <P3 x={0} y={1000} z={-2300} w={6000} h={2400} style={{ background: `linear-gradient(180deg, #0b0b0b 0%, #101010 70%, rgba(229,9,20,${(0.18 * glow).toFixed(3)}) 100%)` }} />
  </>
);
// linhas de neon no chão até a porta
const Lanes: React.FC<{ glow: number; draw?: number }> = ({ glow, draw = 1 }) => (
  <>
    {[-230, 230].map((x) => (
      <P3 key={x} x={x} y={1} z={-150 - 400 * (1 - draw)} rx={90} w={10} h={800 * draw} style={{ background: RED, opacity: 0.25 + 0.75 * glow, boxShadow: `0 0 ${(10 + 30 * glow).toFixed(0)}px rgba(229,9,20,0.9)` }} />
    ))}
    <P3 x={0} y={1} z={-560} rx={90} w={470} h={10} style={{ background: RED, opacity: 0.25 + 0.75 * glow, boxShadow: `0 0 ${(10 + 30 * glow).toFixed(0)}px rgba(229,9,20,0.9)` }} />
  </>
);
// luminárias no alto (as barras brancas inclinadas da referência)
const LAMPS: [number, number, number][] = [[-380, -260, 30], [380, -260, -30], [-380, -760, 30], [380, -760, -30], [0, -1150, 0], [-380, 240, 30], [380, 240, -30]];
const Lamps: React.FC<{ t: number; on: number[] }> = ({ t, on }) => (
  <>
    {LAMPS.map(([x, z, r], i) => {
      const a = on[i] ?? 1e9;
      const fl = t < a ? 0.08 : t < a + 0.25 ? (Math.sin((t - a) * 90) > 0 ? 1 : 0.15) : 1;
      return <P3 key={i} x={x} y={1150} z={z} rx={90} rz={r} w={26} h={300} style={{ background: WHITE, opacity: 0.12 + 0.88 * fl, boxShadow: fl > 0.5 ? "0 0 30px rgba(255,255,255,0.8), 0 0 80px rgba(255,255,255,0.3)" : "none", borderRadius: 6 }} />;
    })}
  </>
);
// a fachada da empresa
const Store: React.FC<{ lit: number; t: number; knock?: number }> = ({ lit, t, knock = 0 }) => {
  const glass = (o: number) => `linear-gradient(170deg, rgba(255,255,255,${(0.06 + 0.1 * o).toFixed(3)}) 0%, rgba(255,255,255,0) 30%), linear-gradient(180deg, rgba(255,235,235,${(0.75 * o).toFixed(3)}) 0%, rgba(229,9,20,${(0.45 * o).toFixed(3)}) 100%), #0a0a0a`;
  const shake = knock * Math.sin(t * 80) * 6;
  return (
    <>
      <Box x={0} y={0} z={-700} w={1000} h={640} d={300} front={{ background: "linear-gradient(180deg, #232323, #151515)", boxShadow: "inset 0 0 0 3px #2c2c2c" }}>
        {/* letreiro */}
        <div style={{ position: "absolute", left: 0, right: 0, top: 0, height: 120, background: "#0d0d0d", borderBottom: `5px solid ${RED}`, boxShadow: `0 6px ${(10 + 40 * lit).toFixed(0)}px rgba(229,9,20,${(0.3 + 0.6 * lit).toFixed(2)})`, display: "flex", alignItems: "center", justifyContent: "center", fontFamily: A, fontSize: 64, letterSpacing: "0.12em", color: `rgba(248,248,248,${(0.25 + 0.75 * lit).toFixed(2)})`, textShadow: lit > 0.3 ? "0 0 18px rgba(255,255,255,0.5)" : "none" }}>SUA EMPRESA</div>
        {/* janelas */}
        {[60, 700].map((x) => (
          <div key={x} style={{ position: "absolute", left: x, top: 190, width: 240, height: 240, background: glass(lit), border: "6px solid #2e2e2e", boxShadow: lit > 0.1 ? `0 0 ${(50 * lit).toFixed(0)}px rgba(229,9,20,${(0.5 * lit).toFixed(2)})` : "none" }} />
        ))}
        {/* porta */}
        <div style={{ position: "absolute", left: 370, top: 200, width: 260, height: 440, background: glass(Math.max(lit, 0.12)), border: "8px solid #303030", borderBottom: "none", transform: `translateX(${shake.toFixed(1)}px)` }}>
          <div style={{ position: "absolute", left: 126, top: 0, bottom: 0, width: 6, background: "#303030" }} />
          <div style={{ position: "absolute", left: 104, top: 220, width: 10, height: 60, borderRadius: 4, background: "#555" }} />
          <div style={{ position: "absolute", left: 146, top: 220, width: 10, height: 60, borderRadius: 4, background: "#555" }} />
        </div>
      </Box>
      {/* calçada */}
      <Box x={0} y={0} z={-470} w={1300} h={18} d={160} front={{ background: "#1e1e1e" }} />
    </>
  );
};
// poeira flutuando
const Dust: React.FC<{ t: number; n?: number; o?: number }> = ({ t, n = 26, o = 0.5 }) => (
  <AbsoluteFill style={{ pointerEvents: "none" }}>
    {Array.from({ length: n }, (_, i) => {
      const r = (q: number) => { const v = Math.sin(i * 91.7 + q * 13.1) * 43758.5; return v - Math.floor(v); };
      const x = (r(1) * 1080 + t * (10 + r(2) * 30)) % 1080;
      const y = (r(3) * 1920 - t * (14 + r(4) * 26) + 3840) % 1920;
      const s = 2 + r(5) * 4;
      return <div key={i} style={{ position: "absolute", left: x, top: y, width: s, height: s, borderRadius: s, background: r(6) > 0.6 ? RED : WHITE, opacity: o * (0.25 + 0.6 * r(7)) * (0.6 + 0.4 * Math.sin(t * 2 + i)) }} />;
    })}
  </AbsoluteFill>
);
const Vignette: React.FC<{ s?: number }> = ({ s = 0.75 }) => (
  <AbsoluteFill style={{ pointerEvents: "none", background: `linear-gradient(180deg, rgba(10,10,10,0.82) 0px, rgba(10,10,10,0.6) 380px, rgba(10,10,10,0) 600px), radial-gradient(ellipse at 50% 46%, rgba(0,0,0,0) 40%, rgba(0,0,0,${s}) 100%)` }} />
);

// clarão de luz nas trocas de cena
const Burst: React.FC<{ t: number; at: number; c?: string; d?: number }> = ({ t, at, c = "255,255,255", d = 0.55 }) => {
  if (t < at - 0.2 || t > at + d) return null;
  const up = lin(t, at - 0.2, at), down = 1 - lin(t, at, at + d);
  const o = Math.min(up, down);
  return (
    <AbsoluteFill style={{ pointerEvents: "none", mixBlendMode: "screen" }}>
      <AbsoluteFill style={{ background: `radial-gradient(circle at 50% 48%, rgba(${c},1) 0%, rgba(229,9,20,0.85) ${(18 + 40 * up).toFixed(0)}%, rgba(14,14,14,0) ${(40 + 50 * up).toFixed(0)}%)`, opacity: o }} />
      <AbsoluteFill style={{ background: `repeating-conic-gradient(from ${(t * 40).toFixed(1)}deg at 50% 48%, rgba(255,255,255,0.5) 0deg 2deg, rgba(255,255,255,0) 2deg 14deg)`, opacity: o * 0.6, maskImage: "radial-gradient(circle at 50% 48%, black 0%, transparent 60%)", WebkitMaskImage: "radial-gradient(circle at 50% 48%, black 0%, transparent 60%)" }} />
    </AbsoluteFill>
  );
};

// barra de leitura sobre o pé da cena (como "ocupação do pátio" na referência)
const Meter: React.FC<{ t: number; at: number; label: string; v: number; red?: boolean; top?: number }> = ({ t, at, label, v, red, top = 1300 }) => (
  <div style={{ position: "absolute", left: 130, right: 130, top, opacity: k(t, at, 0.4) }}>
    <div style={{ display: "flex", justifyContent: "space-between", fontFamily: M, fontWeight: 700, fontSize: 22, letterSpacing: "0.2em", color: GREY, marginBottom: 10 }}>
      <span>{label}</span><span style={{ color: red ? RED : WHITE }}>{Math.round(v)}%</span>
    </div>
    <div style={{ height: 14, borderRadius: 14, background: "rgba(255,255,255,0.1)", overflow: "hidden" }}>
      <div style={{ width: `${v.toFixed(2)}%`, height: "100%", borderRadius: 14, background: RED, boxShadow: glowRed(0.7) }} />
    </div>
  </div>
);

// ícones
const sv = (s: number, c: string, ch: React.ReactNode, w = 2) => (
  <svg width={s} height={s} viewBox="0 0 24 24" fill="none" stroke={c} strokeWidth={w} strokeLinecap="round" strokeLinejoin="round">{ch}</svg>
);
const IcoChat = (s: number, c: string) => sv(s, c, <path d="M20 12a8 8 0 01-11.6 7.1L4 20l1-4.200A8 8 0 1120 12z" />);
const IcoClock = (s: number, c: string) => sv(s, c, <><circle cx="12" cy="12" r="8.500" /><path d="M12 7.500V12l3 2" /></>);
const IcoHeart = (s: number, c: string) => sv(s, c, <path d="M12 20s-7.500-4.600-7.500-10A4.300 4.300 0 0112 7.300 4.300 4.300 0 0119.500 10c0 5.400-7.500 10-7.500 10z" />);
const IcoChart = (s: number, c: string) => sv(s, c, <path d="M4 20V11M10 20V5M16 20v-7M21.500 20H2.500" />);
const IcoAlert = (s: number, c: string) => sv(s, c, <><path d="M12 3.500L2.500 20h19z" /><path d="M12 10v4.500M12 17.300v.200" /></>, 2.4);

// ───────── cena 1 e 2: a fachada apagada (uma tomada só, a câmera recua e depois vem pela lateral até a porta) ─────────
const BUBBLES: [string, number, number, number, number][] = [
  ["Vocês fazem orçamento?", 9.0, -330, 560, -420],
  ["Qual o valor do serviço?", 10.0, 300, 430, -400],
  ["Ainda estão atendendo?", 11.0, -260, 300, -380],
];
const SLoja: React.FC<{ t: number }> = ({ t }) => {
  let cam: Cam;
  if (t < T2) {
    const p = 1 - Math.pow(1 - lin(t, -0.3, T2 + 0.6), 1.6); // recua sem frear antes do corte
    cam = look(mix(-40, 90, p), mix(260, 400, p), mix(-330, 860, p), 0, mix(260, 480, p), -550, mix(1.5, 0, p));
  } else {
    const p = io(t, T2, T3 + 0.3);
    cam = look(mix(-380, -60, p), mix(470, 330, p), mix(820, 20, p), 0, mix(470, 380, p), -550, mix(-2, 0, p));
  }
  const flick = t < 4.05 ? 0.16 + 0.06 * Math.sin(t * 9) : t < 4.3 ? (Math.sin(t * 70) > 0 ? 0.16 : 0) : 0.04; // a luz da porta apaga na "sorte"
  const knock = bump(t, 12.25, 0.25) + bump(t, 12.6, 0.25);
  const fall = lin(t, 4.9, 7.6);
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <World cam={cam}>
        <Floor glow={0.25} />
        <Lanes glow={0.15} />
        <Lamps t={t} on={[0.3, 1e9, 1e9, 1e9, 1e9, 0.9, 1e9]} />
        <Store lit={flick} t={t} knock={knock} />
      </World>
      {/* balões de mensagem sem resposta, um embaixo do outro no eixo central */}
      {t > T2 &&
        BUBBLES.map(([m, at], i) => {
          const e = pop(t, at, 0.5);
          return (
            <div key={i} style={{ position: "absolute", left: 0, right: 0, top: 640 + i * 200, display: "flex", flexDirection: "column", alignItems: "center", opacity: Math.min(1, e * 2), transform: `translateX(${((i - 1) * 40 + Math.sin(t * 1.3 + i) * 10 + bump(t, at + 0.9, 0.4) * 14 * Math.sin(t * 60)).toFixed(1)}px) translateY(${((1 - e) * 60).toFixed(1)}px) scale(${(0.7 + 0.3 * e).toFixed(3)})` }}>
              <div style={{ display: "flex", alignItems: "center", gap: 14, fontFamily: I, fontWeight: 700, fontSize: 38, color: WHITE, background: "rgba(24,24,24,0.95)", border: "2px solid #333", borderRadius: "30px 30px 30px 8px", padding: "18px 30px 18px 18px", whiteSpace: "nowrap", boxShadow: "0 20px 50px rgba(0,0,0,0.7)" }}>
                <div style={{ width: 54, height: 54, borderRadius: 54, background: "#2c2c2c", display: "flex", alignItems: "center", justifyContent: "center" }}>{IcoChat(30, GREY)}</div>
                {m}
              </div>
              <div style={{ display: "flex", alignItems: "center", gap: 8, marginTop: 10, fontFamily: M, fontWeight: 700, fontSize: 21, letterSpacing: "0.1em", color: RED, opacity: lin(t, at + 0.6, at + 0.8) }}>
                {IcoClock(22, RED)} VISUALIZADA · SEM RESPOSTA
              </div>
            </div>
          );
        })}
      <Dust t={t} o={0.35} />
      <Vignette />
      {/* indicador de novos clientes parado no vermelho */}
      {t < T2 + 0.2 && <Meter t={t} at={2.4} label="NOVOS CLIENTES / MÊS" v={mix(34, 9, fall) + Math.sin(t * 7) * 1.2} red top={1340} />}
      <Title t={t} top={190} out={2.42} lines={[{ size: 56, words: [["Empresário", 0.11], ["de", 0.81], ["Três", 0.97], ["Lagoas", 1.21]] }, { size: 56, words: [["e", 1.63], ["região...", 1.75]] }]} />
      <Title t={t} top={190} out={4.7} lines={[{ size: 46, words: [["Empresário de Três Lagoas...", 2.4]] }, { size: 92, words: [["Sua", 2.65], ["empresa", 2.79], ["depende", 3.41]] }, { size: 92, words: [["do", 3.79], ["acaso?", 4.05, true]] }]} />
      <Title t={t} top={190} out={T2 - 0.05} lines={[{ size: 46, words: [["Empresário de Três Lagoas...", 4.7]] }, { size: 92, words: [["Depende", 4.78], ["apenas", 4.88]] }, { size: 92, words: [["de", 4.92], ["indicação?", 4.97, true]] }]} />
      <Title t={t} top={190} lines={[{ size: 96, words: [["Chega", 8.56], ["de", 8.84], ["depender", 8.94]] }, { size: 96, words: [["de", 9.74], ["indicação", 9.84, true]] }]} />
    </AbsoluteFill>
  );
};

// ───────── cena 3: o alerta e o caixa caindo, em barras 3D ─────────
const DAYS = ["SEG", "TER", "QUA", "QUI", "SEX"];
