// ───────── cena 4: o radar de Três Lagoas ─────────
const rnd = (i: number) => { const x = Math.sin(i * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); };
const STREETS = Array.from({ length: 40 }, (_, i) => {
  const h = i % 2 === 0; const c = -400 + rnd(i) * 800; const tilt = (rnd(i + 50) - 0.5) * 160;
  return h ? `M-420 ${c.toFixed(0)} L420 ${(c + tilt).toFixed(0)}` : `M${c.toFixed(0)} -420 L${(c + tilt).toFixed(0)} 420`;
});
const SPOKES = [6, 44, 93, 128, 171, 214, 247, 290, 333];
const BLIPS = Array.from({ length: 30 }, (_, i) => ({ ang: rnd(i + 7) * 360, r: 80 + rnd(i + 90) * 300 }));
const RBUB: [string, number, number, number][] = [["Vi o anúncio de vocês!", 23.0, 300, 230], ["Quero um orçamento", 24.2, 50, 290], ["Têm horário amanhã?", 26.6, 230, 170], ["Atendem minha cidade?", 28.0, 120, 250]];
const SRadar: React.FC<{ t: number }> = ({ t }) => {
  const S = 980;
  const sweep = ((t - T4) * 140) % 360;
  const open = k(t, T4, 0.9);
  const zoom = io(t, 30.15, T5 + 0.1);
  const tilt = mix(24, 10, io(t, T4, T5));
  return (
    <AbsoluteFill style={{ background: BLACK }}>
      <AbsoluteFill style={{ perspective: 1400 }}>
        <div style={{ position: "absolute", left: 540 - S / 2, top: 900 - S / 2, width: S, height: S, transform: `rotateX(${tilt.toFixed(2)}deg) rotateZ(${((t - T4) * 2.5).toFixed(2)}deg) scale(${(mix(0.82, 1.0, io(t, T4, 30)) * (1 + 3.5 * zoom * zoom)).toFixed(4)})`, transformStyle: "preserve-3d" }}>
          <svg width={S} height={S} viewBox="-450 -450 900 900" style={{ position: "absolute", inset: 0, overflow: "visible" }}>
            <defs><clipPath id="rc2"><circle r={420 * open} /></clipPath></defs>
            <circle r={430} fill="rgba(229,9,20,0.05)" />
            <g clipPath="url(#rc2)" stroke="rgba(229,9,20,0.2)" strokeWidth={2} fill="none">{STREETS.map((d, i) => <path key={i} d={d} />)}</g>
            {[420, 315, 210, 105].map((r, i) => (
              <circle key={r} r={r * k(t, T4 + i * 0.08, 0.7)} fill="none" stroke={RED} strokeOpacity={i === 0 ? 0.95 : 0.45} strokeWidth={i === 0 ? 4 : 2} strokeDasharray={i === 0 ? undefined : "6 10"} />
            ))}
            {SPOKES.map((a, i) => {
              const l = 420 * k(t, T4 + 0.1 + i * 0.04, 0.6);
              const rad = ((a - 90) * Math.PI) / 180;
              return <line key={a} x1={0} y1={0} x2={Math.cos(rad) * l} y2={Math.sin(rad) * l} stroke={RED} strokeOpacity={0.55} strokeWidth={2.5} />;
            })}
            {[["80 KM", 420], ["60 KM", 315], ["40 KM", 210], ["20 KM", 105]].map(([l, r]) => (
              <text key={l as string} x={10} y={-(r as number) + 28} fill={RED} fontFamily={M} fontSize={20} fontWeight={700} opacity={open}>{l}</text>
            ))}
          </svg>
          {/* varredura */}
          <div style={{ position: "absolute", inset: S * (30 / 900), borderRadius: "50%", opacity: open, background: `conic-gradient(from ${sweep.toFixed(1)}deg, rgba(229,9,20,0) 0deg, rgba(229,9,20,0) 290deg, rgba(229,9,20,0.6) 360deg)` }} />
          {BLIPS.map((b, i) => {
            const behind = (((sweep + 90 - b.ang) % 360) + 360) % 360;
            const g = Math.exp(-behind / 70);
            const x = S / 2 + Math.cos(((b.ang - 90) * Math.PI) / 180) * b.r * (S / 900);
            const y = S / 2 + Math.sin(((b.ang - 90) * Math.PI) / 180) * b.r * (S / 900);
            return <div key={i} style={{ position: "absolute", left: x - 8, top: y - 8, width: 16, height: 16, borderRadius: 16, background: RED, opacity: (0.3 + 0.7 * g) * lin(t, T4 + 0.5, T4 + 1.2), boxShadow: `0 0 ${(6 + 24 * g).toFixed(0)}px rgba(229,9,20,0.95)` }} />;
          })}
          {/* balões presos ao mapa */}
          {RBUB.map(([m, at, ang, r], i) => {
            const e = pop(t, at, 0.45);
            const x = S / 2 + Math.cos(((ang - 90) * Math.PI) / 180) * r * (S / 900);
            const y = S / 2 + Math.sin(((ang - 90) * Math.PI) / 180) * r * (S / 900);
            return (
              <div key={i} style={{ position: "absolute", left: x, top: y, opacity: Math.min(1, e * 2), transform: `translate(-50%, -120%) rotateZ(${(-(t - T4) * 2.5).toFixed(2)}deg) scale(${(0.5 + 0.5 * e).toFixed(3)})` }}>
                <div style={{ display: "flex", alignItems: "center", gap: 10, fontFamily: I, fontWeight: 700, fontSize: 27, color: WHITE, background: "rgba(20,20,20,0.95)", border: `2px solid ${RED}`, borderRadius: 34, padding: "10px 22px 10px 10px", whiteSpace: "nowrap", boxShadow: "0 0 24px rgba(229,9,20,0.45)" }}>
                  <div style={{ width: 40, height: 40, borderRadius: 40, background: RED, display: "flex", alignItems: "center", justifyContent: "center" }}>{IcoChat(24, WHITE)}</div>
                  {m}
                </div>
              </div>
            );
          })}
          {/* centro: a Fourp em Três Lagoas */}
          <div style={{ position: "absolute", left: S / 2, top: S / 2, transform: `translate(-50%, -50%) rotateZ(${(-(t - T4) * 2.5).toFixed(2)}deg) scale(${pop(t, T4 + 0.2, 0.6).toFixed(3)})`, display: "flex", flexDirection: "column", alignItems: "center", gap: 8 }}>
            <div style={{ width: 128, height: 128, borderRadius: 128, background: BLACK, border: `5px solid ${RED}`, boxShadow: glowRed(1 + 0.5 * Math.sin(t * 5)), display: "flex", alignItems: "center", justifyContent: "center" }}>
              <Img src={staticFile("johny/simbolo.png")} style={{ width: 96, height: 96 }} />
            </div>
            <div style={{ fontFamily: M, fontWeight: 700, fontSize: 22, letterSpacing: "0.18em", color: WHITE, background: "rgba(14,14,14,0.85)", padding: "2px 10px" }}>TRÊS LAGOAS</div>
          </div>
        </div>
      </AbsoluteFill>
      <div style={{ position: "absolute", left: 0, right: 0, top: 1390, display: "flex", justifyContent: "center", gap: 16, opacity: k(t, 21.4) * (1 - zoom) }}>
        {["RAIO 80 KM", "TRÊS LAGOAS E REGIÃO"].map((s) => (
          <div key={s} style={{ fontFamily: M, fontWeight: 700, fontSize: 22, letterSpacing: "0.16em", color: WHITE, border: "2px solid #3a3a3a", background: "rgba(14,14,14,0.85)", borderRadius: 30, padding: "6px 18px" }}>{s}</div>
        ))}
      </div>
      <Dust t={t} o={0.3} />
      <Vignette s={0.6} />
      <Title t={t} top={170} out={25.75} tag={["A FOURP CRIA", 20.61]} lines={[{ size: 84, words: [["Sistema", 21.71], ["de", 22.23], ["aquisição", 22.33]] }, { size: 84, words: [["e", 22.87], ["conversão", 22.97, true]] }]} />
      <Title t={t} top={170} out={30.4} tag={["META ADS · GOOGLE ADS · CRM", 25.88]} lines={[{ size: 70, words: [["Tráfego", 26.58], ["qualificado", 27.12]] }, { size: 70, words: [["+", 28.02], ["tecnologia", 28.26], ["própria", 28.98]] }, { size: 70, words: [["+", 29.58], ["CRM", 29.74, true]] }]} />
    </AbsoluteFill>
  );
};

