// legenda da fala: o grupo inteiro aparece e a palavra da vez ganha a caixa vermelha (como na referência)
const CHUNKS: [string, number, number][][] = (() => {
  const out: [string, number, number][][] = [];
  let cur: [string, number, number][] = [];
  PALAVRAS.forEach((w, i) => {
    cur.push(w);
    const nxt = PALAVRAS[i + 1];
    const end = /[.,?!]$/.test(w[0]) || cur.length >= 3 || cur.map((c) => c[0]).join(" ").length > 16 || (nxt && nxt[1] - w[2] > 0.4);
    if (end) { out.push(cur); cur = []; }
  });
  if (cur.length) out.push(cur);
  return out;
})();
const Captions: React.FC<{ t: number }> = ({ t }) => {
  const idx = CHUNKS.findIndex((c, i) => t >= c[0][1] - 0.05 && (i + 1 >= CHUNKS.length ? t < c[c.length - 1][2] + 0.8 : t < CHUNKS[i + 1][0][1] - 0.05));
  if (idx < 0) return null;
  const c = CHUNKS[idx];
  const e = k(t, c[0][1] - 0.05, 0.18);
  return (
    <div style={{ position: "absolute", left: 100, right: 100, top: 1545, display: "flex", justifyContent: "center", gap: 16, opacity: e, transform: `scale(${(0.9 + 0.1 * e).toFixed(3)})` }}>
      {c.map(([w, a], i) => {
        const on = t >= a - 0.03 && (i + 1 >= c.length || t < c[i + 1][1] - 0.03);
        return (
          <span key={i} style={{ fontFamily: A, fontSize: 56, lineHeight: 1.15, color: WHITE, background: on ? RED : "transparent", boxShadow: on ? glowRed(0.6) : "none", padding: "0 12px", borderRadius: 8, whiteSpace: "nowrap" }}>
            {w.replace(/[.,]$/, "")}
          </span>
        );
      })}
    </div>
  );
};

